1. What is the output?
class A {
    A() { System.out.println("A"); }
}
class B extends A {
    B() { System.out.println("B"); }
}
class C extends B {
    C() { System.out.println("C"); }
}
public class Test {
    public static void main(String[] args) { new C(); }
}

2. Will this compile? If not, why?
class Animal {
    Animal(String name) {
        System.out.println("Animal: " + name);
    }
}
class Dog extends Animal {
    Dog() {
        System.out.println("Dog created");
    }
}

3. What is the output?
class Parent {
    String name = "Parent";
    void display() { System.out.println("Parent: " + name); }
}
class Child extends Parent {
    String name = "Child";  // Field hiding
    @Override
    void display() { System.out.println("Child: " + name); }
}
public class Test {
    public static void main(String[] args) {
        Parent p = new Child();
        p.display();
        System.out.println(p.name);
    }
}

5. Identify the LSP violation:
class Bird {
    public void fly() { System.out.println("Flying..."); }
    public void eat() { System.out.println("Eating..."); }
}
class Penguin extends Bird {
    @Override
    public void fly() {
        throw new UnsupportedOperationException("Penguins cannot fly!");
    }
}

6. What is the output?
class Base {
    static void staticMethod() { System.out.println("Base static"); }
    void instanceMethod()      { System.out.println("Base instance"); }
}
class Derived extends Base {
    static void staticMethod()  { System.out.println("Derived static"); }
    @Override
    void instanceMethod()       { System.out.println("Derived instance"); }
}
public class Test {
    public static void main(String[] args) {
        Base obj = new Derived();
        obj.staticMethod();
        obj.instanceMethod();
    }
}
